//! RULE: the experiment report an ENDED experiment owes is generated by whichever call
//! materialises that end — including a `StartExperiment` that mints a brand new experiment,
//! whose store-wide settle ends every OTHER run whose span had already elapsed.
//!
//! `StartExperiment` settles every experiment in the account before it takes its
//! active-experiment quota, so a fresh start is the call that materialises the end of every
//! run the clock had already finished. The end of a run is what makes the report generation
//! due, so that same call owes the second write for each of those runs: the report object is
//! written to the Amazon S3 output each experiment's configuration names, and a later read
//! reports the generation that already happened. A client whose only FIS traffic is
//! `StartExperiment` therefore never has to call some other operation for the report of an
//! experiment that ended to exist.
//!
//! The sibling [`crate::report_follows_whoever_ends_the_run`] suite spans the operation that
//! observes the end (`ListExperiments`, `StopExperiment`, `UpdateSafetyLeverState`, and a
//! `StartExperiment` REPLAY). This suite takes the start that mints a NEW experiment and
//! spans what that generalises over:
//!
//! * the fresh start naming ANOTHER template, naming the SAME template as the ended run, and
//!   the two starts that mint nothing because the service REFUSES them (a template that is
//!   not there, a `clientToken` carried by a different request) — the settle happened either
//!   way, so the report is owed whatever the caller is then answered;
//! * the status the ended run reached (`completed` for a run whose actions elapsed, `failed`
//!   for one whose target resolved to nothing);
//! * the form of the configured output prefix (none at all, a trailing slash, a nested
//!   prefix).
//!
//! Between the start of the observed run and the ONE fresh start, a row makes no FIS call at
//! all: the object storage it reads settles nothing and drains nothing, so the report it
//! finds can only have been written by that fresh start. The observed experiment is not read
//! through FIS until after the object is there.

use std::time::Duration;

use serde_json::json;
use smithy_server_runtime::MultiServiceRouter;

use crate::experiment_lifecycle::{get_experiment, start_experiment, token, Answer};
use crate::experiment_state_reason_and_report::{
    emulator_with_object_storage, given_report_bucket, template_for, Ending, BUCKET,
};
use crate::report_follows_whoever_ends_the_run::{
    assert_generation_names_object, report_configuration, report_object,
};

/// How long every row waits for the run it started to have ELAPSED on the emulator's
/// compressed run clock: the whole span of a run whose action names the shortest wait
/// (`MIN_RUN_SPAN`) plus the transitions around it, and slack for a loaded machine. Taken
/// ONCE for all rows, since each row has its own emulator.
const PAST_THE_RUN: Duration = Duration::from_secs(9);

/// An `ExperimentTemplateId` this service never minted — well-typed (`^[\S]+$`, within
/// `@length(0..64)`) and naming nothing.
const UNMINTED_TEMPLATE_ID: &str = "EXTTHISTEMPLATEWASNEVERMINTED";

/// The fresh `StartExperiment` a row makes once its first run has elapsed: a start that is
/// not a replay of anything, so it settles the store on its way to minting — or to refusing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FreshStart {
    /// A start from a second template, which configures no report of its own.
    FromAnotherTemplate,
    /// A start from the SAME template the ended run came from, so the minted experiment
    /// configures a report too — one that is not due, because its run has not ended.
    FromTheSameTemplate,
    /// A start naming a template that is not there: refused, after the same settle.
    NamingAnUnmintedTemplate,
    /// A start carrying the `clientToken` of the first start on a request that start never
    /// made: refused for the token, after the same settle.
    CarryingTheTokenOfAnotherRequest,
}

/// One row: how its first run ends, where its report goes, which fresh start observes that
/// end, and how that start is answered.
#[derive(Debug, Clone, Copy)]
struct Row {
    case: &'static str,
    ending: Ending,
    /// The `prefix` the configured output names, or `None` for an output that names none.
    prefix: Option<&'static str>,
    /// The key the report object must be written under, with `{id}` standing for the
    /// experiment id. Spelled out per row rather than computed by the crate.
    key: &'static str,
    start: FreshStart,
    /// The HTTP status the fresh start answers with.
    status: u16,
    /// The wire error code (`__type`) it carries, or `None` when the start is accepted.
    code: Option<&'static str>,
}

fn rows() -> Vec<Row> {
    vec![
        Row {
            case: "fresh-start-from-another-template",
            ending: Ending::Elapses,
            prefix: None,
            key: "{id}/experiment-report.json",
            start: FreshStart::FromAnotherTemplate,
            status: 200,
            code: None,
        },
        Row {
            case: "fresh-start-from-the-same-template",
            ending: Ending::Elapses,
            prefix: Some("fresh/"),
            key: "fresh/{id}/experiment-report.json",
            start: FreshStart::FromTheSameTemplate,
            status: 200,
            code: None,
        },
        Row {
            case: "fresh-start-refused-for-a-template-that-is-not-there",
            ending: Ending::Elapses,
            prefix: Some("refused/template"),
            key: "refused/template/{id}/experiment-report.json",
            start: FreshStart::NamingAnUnmintedTemplate,
            status: 404,
            code: Some("ResourceNotFoundException"),
        },
        Row {
            case: "fresh-start-refused-for-the-token-of-another-request",
            ending: Ending::EmptyTargetResolution,
            prefix: Some("refused/token"),
            key: "refused/token/{id}/experiment-report.json",
            start: FreshStart::CarryingTheTokenOfAnotherRequest,
            status: 409,
            code: Some("ConflictException"),
        },
    ]
}

/// The run a row started and the templates its fresh start can name.
struct Observed {
    id: String,
    template_id: String,
    /// The second template, created up front so the fresh start below is the only FIS call
    /// a row makes after its run begins. Empty for a row that names no second template.
    other_template_id: String,
    client_token: String,
}

/// Create `row`'s template (and, where the row needs one, a second template configuring no
/// report), and start the experiment whose end the fresh start will materialise.
async fn start_the_observed_run(router: &MultiServiceRouter, row: &Row) -> Observed {
    let template_id = template_for(
        router,
        row.case,
        row.ending,
        json!({ "experimentReportConfiguration": report_configuration(row.prefix, BUCKET) }),
    )
    .await;

    let other_template_id = if row.start == FreshStart::FromAnotherTemplate {
        template_for(
            router,
            &format!("{}-other", row.case),
            Ending::Elapses,
            json!({}),
        )
        .await
    } else {
        String::new()
    };

    let client_token = token(&format!("fresh-start-observed-{}", row.case));
    let started = start_experiment(
        router,
        json!({
            "clientToken": client_token,
            "experimentTemplateId": template_id
        }),
    )
    .await;
    assert_eq!(
        started.status, 200,
        "case {:?}: expected the start to be accepted, got {} with {:?}",
        row.case, started.status, started.body
    );
    let experiment = started.member("experiment").clone();
    assert_eq!(
        experiment["experimentReport"]["state"]["status"]
            .as_str()
            .unwrap_or_default(),
        "pending",
        "case {:?}: a report is pending until its experiment ends, got {experiment:?}",
        row.case
    );
    let id = experiment["id"]
        .as_str()
        .unwrap_or_else(|| panic!("case {:?}: no experiment id in {experiment:?}", row.case))
        .to_string();

    Observed {
        id,
        template_id,
        other_template_id,
        client_token,
    }
}

/// Make `row`'s fresh `StartExperiment` — the one call that observes the end of the run
/// above, by settling the store on its way to minting a new experiment or to refusing.
async fn fresh_start(router: &MultiServiceRouter, row: &Row, observed: &Observed) -> Answer {
    let body = match row.start {
        FreshStart::FromAnotherTemplate => json!({
            "clientToken": token(&format!("fresh-start-other-{}", row.case)),
            "experimentTemplateId": observed.other_template_id
        }),
        FreshStart::FromTheSameTemplate => json!({
            "clientToken": token(&format!("fresh-start-same-{}", row.case)),
            "experimentTemplateId": observed.template_id
        }),
        FreshStart::NamingAnUnmintedTemplate => json!({
            "clientToken": token(&format!("fresh-start-unminted-{}", row.case)),
            "experimentTemplateId": UNMINTED_TEMPLATE_ID
        }),
        // The token of the accepted start above, on a request that would tag the experiment
        // differently: not the request that token started.
        FreshStart::CarryingTheTokenOfAnotherRequest => json!({
            "clientToken": observed.client_token,
            "experimentTemplateId": observed.template_id,
            "tags": { "fresh": "no" }
        }),
    };
    start_experiment(router, body).await
}

/// RULE: a `StartExperiment` that mints a new experiment writes the report every run its own
/// settle just ended makes due, to the output that run's configuration names.
#[tokio::test]
async fn a_fresh_start_writes_the_report_of_every_run_its_settle_ends() {
    let rows = rows();

    // Every row's run is started first, each on its own emulator — the settle and the
    // generation are whole-store, so a call another row made would end this row's run and
    // the case would prove nothing about the call under test — and the wait for the runs to
    // elapse is then taken ONCE rather than once per row.
    let mut observed = Vec::new();
    for row in &rows {
        let router = emulator_with_object_storage();
        given_report_bucket(&router).await;
        let run = start_the_observed_run(&router, row).await;
        observed.push((row, router, run));
    }

    // The runs elapse with NO call to FIS made: the end each one now owes the clock has been
    // materialised by nobody.
    tokio::time::sleep(PAST_THE_RUN).await;

    for (row, router, run) in &observed {
        let key = row.key.replace("{id}", &run.id);
        assert!(
            report_object(router, row.case, &key).await.is_none(),
            "case {:?}: no call has ended this run yet, so its report cannot have been \
             written to s3://{BUCKET}/{key}",
            row.case
        );

        let answer = fresh_start(router, row, run).await;
        assert_eq!(
            answer.status, row.status,
            "case {:?}: expected HTTP {}, got {} with {:?}",
            row.case, row.status, answer.status, answer.body
        );
        if let Some(code) = row.code {
            assert_eq!(
                answer.error_code(),
                code,
                "case {:?}: expected {code}, got {:?}",
                row.case,
                answer.body
            );
        }

        // That one call materialised the end of the first run, so it is the call that wrote
        // the report that end made due.
        let document = report_object(router, row.case, &key)
            .await
            .unwrap_or_else(|| {
                panic!(
                    "case {:?}: the start that ended run {} must write its report to \
                     s3://{BUCKET}/{key}",
                    row.case, run.id
                )
            });
        assert_eq!(
            document["experiment"]["id"].as_str().unwrap_or_default(),
            run.id.as_str(),
            "case {:?}: expected the report to be about {}, got {document:?}",
            row.case,
            run.id
        );
        assert_eq!(
            document["experiment"]["state"]["status"]
                .as_str()
                .unwrap_or_default(),
            row.ending.terminal(),
            "case {:?}: expected the report to state the status the run ended in, got {:?}",
            row.case,
            document["experiment"]["state"]
        );

        // The experiment the fresh start MINTED owes nothing yet: its run has not ended, so
        // the sweep writes the reports of ended runs and of no others.
        if row.start == FreshStart::FromTheSameTemplate {
            let minted = answer.member("experiment")["id"]
                .as_str()
                .unwrap_or_else(|| panic!("case {:?}: no minted id in {:?}", row.case, answer.body))
                .to_string();
            let minted_key = row.key.replace("{id}", &minted);
            assert!(
                report_object(router, row.case, &minted_key).await.is_none(),
                "case {:?}: the experiment this start minted has not ended, so no report may \
                 be at s3://{BUCKET}/{minted_key}",
                row.case
            );
        }

        // And the first read of the ended experiment finds the generation that already
        // happened, naming the one object that was written: this read changes nothing.
        let read = get_experiment(router, &run.id)
            .await
            .member("experiment")
            .clone();
        assert_eq!(
            read["state"]["status"].as_str().unwrap_or_default(),
            row.ending.terminal(),
            "case {:?}: expected the run to end {}, got {read:?}",
            row.case,
            row.ending.terminal()
        );
        assert_generation_names_object(row.case, &read["experimentReport"], &key);
    }
}

/// RULE, from the other side: a client whose only FIS traffic is `StartExperiment` sees the
/// report of each run it finished, so two starts in a row leave both earlier runs reported.
///
/// The table above makes ONE fresh start per row. This case makes two in sequence, so the
/// second start is the one that must have ended — and reported — the run the FIRST start
/// began: the rule holds for every run the sweep ends, not only for the oldest one.
#[tokio::test]
async fn each_start_in_a_sequence_reports_the_runs_the_earlier_starts_began() {
    let router = emulator_with_object_storage();
    given_report_bucket(&router).await;

    let case = "start-only-client";
    let template_id = template_for(
        &router,
        case,
        Ending::Elapses,
        json!({
            "experimentReportConfiguration": report_configuration(Some("sequence"), BUCKET)
        }),
    )
    .await;

    // A -> B -> C, each start the only FIS call the client makes, with the run of everything
    // started so far elapsed by the time the next start is made.
    let mut ids: Vec<String> = Vec::new();
    for (index, step) in ["a", "b", "c"].iter().enumerate() {
        // Every run started so far elapses before the next start is made, with no FIS call
        // in between.
        if index > 0 {
            tokio::time::sleep(PAST_THE_RUN).await;
        }
        let answer = start_experiment(
            &router,
            json!({
                "clientToken": token(&format!("start-only-{case}-{step}")),
                "experimentTemplateId": template_id
            }),
        )
        .await;
        assert_eq!(
            answer.status, 200,
            "case {case:?}: expected start {step:?} to be accepted, got {} with {:?}",
            answer.status, answer.body
        );
        let id = answer.member("experiment")["id"]
            .as_str()
            .unwrap_or_else(|| panic!("case {case:?}: no experiment id in {:?}", answer.body))
            .to_string();

        // Every run started before this one has elapsed, so this start ended it — and wrote
        // its report.
        for earlier in &ids {
            let key = format!("sequence/{earlier}/experiment-report.json");
            assert!(
                report_object(&router, case, &key).await.is_some(),
                "case {case:?}: start {step:?} ended run {earlier}, so it must have written \
                 its report to s3://{BUCKET}/{key}"
            );
        }

        ids.push(id);
    }

    // Read back only at the end: each report names the object the start that ended its run
    // had already written.
    for id in &ids[..2] {
        let key = format!("sequence/{id}/experiment-report.json");
        let read = get_experiment(&router, id).await.member("experiment").clone();
        assert_eq!(
            read["state"]["status"].as_str().unwrap_or_default(),
            "completed",
            "case {case:?}: expected run {id} to have completed, got {read:?}"
        );
        assert_generation_names_object(case, &read["experimentReport"], &key);
    }
}
